mapper.sql:
WHERE search_vec @@ query
AND doc_type = #{docType}
AND category = #{category}
AND source_updated_at >= #{fromTs}
AND source_updated_at < #{toTs}

mapper.select:
SELECT doc_type, doc_id, title, summary, link_url, category, source_updated_at, ts_rank(search_vec, query) AS rank FROM tn_search_index, to_tsquery('simple', #{tsquery}) query
ORDER BY source_updated_at DESC, doc_id DESC ORDER BY rank DESC, doc_id DESC
LIMIT #{size} OFFSET #{offset}

SELECT * FROM (
    SELECT doc_type, doc_id, title, summary, link_url, category, source_updated_at,
           ts_rank(search_vec, query) AS rank,
           row_number() OVER (PARTITION BY doc_type

                   ORDER BY source_updated_at DESC, doc_id DESC
                   ORDER BY ts_rank(search_vec, query) DESC, doc_id DESC

           ) AS rn,
           count(*) OVER (PARTITION BY doc_type) AS type_total
    FROM tn_search_index,
         to_tsquery('simple', #{tsquery}) query
    WHERE search_vec @@ query
    AND source_updated_at >= #{fromTs}
    AND source_updated_at < #{toTs}
) t
WHERE rn <= #{groupSize}
ORDER BY doc_type, rn

SELECT category AS key, count(*) AS count
FROM tn_search_index,
     to_tsquery('simple', #{tsquery}) query
WHERE search_vec @@ query
  AND doc_type = #{docType}
  AND category IS NOT NULL
AND source_updated_at >= #{fromTs}
AND source_updated_at < #{toTs}
GROUP BY category
ORDER BY count DESC, category

SELECT title FROM (
    SELECT DISTINCT title, similarity(title, #{q}) AS sim
    FROM tn_search_index
    WHERE title % #{q}
       OR title ILIKE '%' || #{q} || '%'
) t
ORDER BY sim DESC, title
LIMIT #{limit}
